// https://opensource.adobe.com/spectrum-web-components/components/action-bar
// Currently, there is no Action Bar component in RS2. This PR adds the SWC ActionBar as part of the Spectrum Wrapper set of components. Clients will use the wrapper instead of the SWC directly and maintain their own React fallback (unless an RS2 action bar is created in the future).
// Even without RS2 fallback, library consistency will provide benefits such as bundle size optimization with version pinning and web component registration
import type { ActionBar as ActionBarType } from '@ccx-public/spectrum-web-component-fallbacks/dist/action-bar';
import React, { forwardRef, useEffect, useRef } from 'react';
import { filterBooleanProps, useComponent } from './utils';
import createWrapper from './utils/createWrapper';
import mergeRefs from './utils/mergeRefs';
import { SWCLoader } from './utils/SWCLoader';

let swcLoader;
if (!process.env.EXCLUDE_SWC) {
    swcLoader = new SWCLoader(['sp-action-bar'], async () => {
        const { ActionBar } = await import(
            /* webpackChunkName: "SpActionBar" */
            '@ccx-public/spectrum-web-component-fallbacks/dist/action-bar'
        );
        return [ActionBar];
    });
}

type ActionBarCompatProps = {
    onClose?: () => void;
};

// Currently, no action bar exists in RS2 for fallback
export default createWrapper<ActionBarType, ActionBarCompatProps>({
    displayName: 'ActionBar',
    fallback: undefined,
    swcLoader,
    SWCWrapper: forwardRef(function SpActionBar(props, ref) {
        const { className, flexible, open, emphasized, onClose, ...rest } =
            props;
        const actionBarRef = useRef<ActionBarType>();

        useEffect(() => {
            const actionBar = actionBarRef.current;
            if (actionBar && onClose) {
                actionBar.addEventListener('close', onClose);
            }

            return () => {
                if (actionBar && onClose) {
                    actionBar.removeEventListener('close', onClose);
                }
            };
        }, [onClose]);

        const swcProps = {
            ...filterBooleanProps({
                emphasized,
                flexible,
                open,
            }),
            class: className,
            ...rest,
        };

        const ActionBar = useComponent('sp-action-bar');

        return <ActionBar {...swcProps} ref={mergeRefs([actionBarRef, ref])} />;
    }),
    tagName: 'sp-action-bar',
});
